export const NAV_CSS = "/*\n * Al Ummah Now navigation contract (docs/design/NAV.md): the header account button, the account\n * menu and every menu that opens from the header, in every app (videos web, videos admin, www,\n * CMS, profile, auth admin). Framework-free: plain class names, any markup that follows NAV.md.\n *\n * Fanous tokens only. Every app vendors this file at a pinned commit (each repo's sync script);\n * fallbacks equal the token values so an app that vendors only the colour tokens still renders the\n * same sizes. Logical properties only, so it mirrors in RTL with no extra rules.\n *\n * The header is dark in every theme and mode: header controls use the nav tokens. A menu is not\n * part of the header: it is a page surface (the page's surface, background, text and divider\n * tokens), light in light mode and dark in dark, and resets text colours, so it never inherits the\n * header's light text.\n */\n\n/* ---------- header controls (on the dark header) ---------- */\n.aun-acct-btn,\n.aun-icon-btn,\n.aun-lang {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--fanous-spacing-sm, 8px);\n  min-height: 2.5rem;\n  min-width: 2.5rem;\n  margin: 0;\n  padding-block: 0;\n  padding-inline: var(--fanous-spacing-sm, 8px);\n  border: 1px solid var(--fanous-c-nav-search-border);\n  border-radius: var(--fanous-radius-full, 999px);\n  background: transparent;\n  color: var(--fanous-c-nav-text);\n  font: inherit;\n  font-size: 0.9375rem;\n  font-weight: 500;\n  line-height: 1.2;\n  text-decoration: none;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n}\n.aun-icon-btn {\n  padding-inline: 0;\n}\n.aun-acct-btn {\n  max-width: 15rem;\n  padding-inline: var(--fanous-spacing-xs, 4px) var(--fanous-spacing-sm, 8px);\n}\n.aun-acct-btn:hover,\n.aun-icon-btn:hover,\n.aun-lang:hover,\n.aun-acct-btn[aria-expanded='true'],\n.aun-icon-btn[aria-expanded='true'] {\n  background: var(--fanous-c-nav-hover);\n}\n.aun-acct-btn:focus-visible,\n.aun-icon-btn:focus-visible,\n.aun-lang:focus-visible {\n  outline: 2px solid var(--fanous-c-nav-active-text);\n  outline-offset: 2px;\n}\n.aun-acct-btn svg,\n.aun-icon-btn svg {\n  width: 1.125rem;\n  height: 1.125rem;\n  flex: none;\n}\n.aun-acct-btn .aun-caret {\n  width: 0.875rem;\n  height: 0.875rem;\n  color: var(--fanous-c-nav-icon);\n}\n.aun-acct-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* phone: the button is the avatar and the caret; the name is still its accessible name */\n@media (max-width: 30rem) {\n  .aun-acct-btn .aun-acct-name {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    overflow: hidden;\n    clip-path: inset(50%);\n    white-space: nowrap;\n  }\n}\n\n/* ---------- avatar (image, else the name's first letter) ---------- */\n.aun-avatar {\n  display: inline-grid;\n  place-items: center;\n  flex: none;\n  width: 1.75rem;\n  height: 1.75rem;\n  border-radius: var(--fanous-radius-full, 999px);\n  overflow: hidden;\n  background: var(--fanous-color-primary);\n  color: var(--fanous-color-on-primary);\n  font-size: 0.8125rem;\n  font-weight: 700;\n  line-height: 1;\n  object-fit: cover;\n  text-transform: uppercase;\n}\n.aun-avatar img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.aun-avatar--sm {\n  width: 1.5rem;\n  height: 1.5rem;\n  font-size: 0.75rem;\n}\n.aun-avatar--lg {\n  width: 2.5rem;\n  height: 2.5rem;\n  font-size: 1rem;\n}\n\n/* ---------- menu surface ---------- */\n.aun-menu {\n  /* The page's own colours, never the dark header's (owner review, 2026-11-12): light surfaces in\n     light mode, dark in dark. Hover and the current row take the page background. */\n  --aun-menu-bg: var(--fanous-color-surface);\n  --aun-menu-text: var(--fanous-color-text-primary);\n  --aun-menu-muted: var(--fanous-color-text-secondary);\n  --aun-menu-hover: var(--fanous-color-background);\n  --aun-menu-line: var(--fanous-color-divider);\n  position: absolute;\n  inset-inline-end: 0;\n  inset-block-start: calc(100% + var(--fanous-spacing-sm, 8px));\n  z-index: 60;\n  box-sizing: border-box;\n  min-width: 16rem;\n  max-width: min(20rem, calc(100vw - 2 * var(--fanous-spacing-sm, 8px)));\n  max-height: calc(100dvh - 5rem);\n  overflow-y: auto;\n  margin: 0;\n  padding: var(--fanous-spacing-xs, 4px);\n  list-style: none;\n  background: var(--aun-menu-bg);\n  color: var(--aun-menu-text);\n  border: 1px solid var(--aun-menu-line);\n  border-radius: var(--fanous-radius-md, 8px);\n  box-shadow: var(--fanous-elevation-medium);\n  font-size: 0.9375rem;\n  font-weight: 400;\n  line-height: 1.35;\n  text-align: start;\n}\n.aun-menu[hidden] {\n  display: none;\n}\n.aun-menu ul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.aun-menu li {\n  margin: 0;\n}\n/* phone: a sheet under the header, the full width less a small gutter */\n@media (max-width: 30rem) {\n  .aun-menu {\n    position: fixed;\n    inset-inline: var(--fanous-spacing-sm, 8px);\n    inset-block-start: calc(var(--aun-header-height, 3.5rem) + var(--fanous-spacing-xs, 4px));\n    min-width: 0;\n    max-width: none;\n    max-height: calc(100dvh - var(--aun-header-height, 3.5rem) - var(--fanous-spacing-lg, 16px));\n  }\n}\n\n/* who is signed in */\n.aun-menu-who {\n  display: flex;\n  align-items: center;\n  gap: var(--fanous-spacing-md, 12px);\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-md, 12px);\n}\n.aun-menu-who-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n.aun-menu-who-name {\n  font-weight: 600;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.aun-menu-who-sub,\n.aun-acct-email,\n.aun-acct-current {\n  color: var(--aun-menu-muted);\n  font-size: 0.8125rem;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* section label */\n.aun-menu-label {\n  display: block;\n  margin: 0;\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-md, 12px) var(--fanous-spacing-xxs, 2px);\n  color: var(--aun-menu-muted);\n  font-size: 0.75rem;\n  font-weight: 600;\n  letter-spacing: 0;\n  text-transform: none;\n}\n\n/* separator */\n.aun-menu-sep {\n  height: 0;\n  margin: var(--fanous-spacing-xs, 4px) calc(-1 * var(--fanous-spacing-xs, 4px));\n  padding: 0;\n  border: 0;\n  border-block-start: 1px solid var(--aun-menu-line);\n}\n\n/* item: a link or a button */\n.aun-menu-item {\n  display: flex;\n  align-items: center;\n  gap: var(--fanous-spacing-md, 12px);\n  box-sizing: border-box;\n  width: 100%;\n  min-height: 2.75rem;\n  margin: 0;\n  padding: var(--fanous-spacing-xs, 4px) var(--fanous-spacing-md, 12px);\n  border: 0;\n  border-radius: var(--fanous-radius-sm, 4px);\n  background: transparent;\n  color: var(--aun-menu-text);\n  font: inherit;\n  text-align: start;\n  text-decoration: none;\n  cursor: pointer;\n}\n.aun-menu-item:hover,\n.aun-menu-item:focus-visible {\n  background: var(--aun-menu-hover);\n  color: var(--aun-menu-text);\n  text-decoration: none;\n}\n.aun-menu-item:focus-visible,\n.aun-acct-signout:focus-visible {\n  outline: 2px solid var(--fanous-color-focus-ring);\n  outline-offset: -2px;\n}\n.aun-menu-item:active {\n  background: var(--aun-menu-hover);\n}\n.aun-menu-item[disabled],\n.aun-menu-item[aria-disabled='true'] {\n  cursor: progress;\n  opacity: 0.6;\n}\n/* the current account and a context line are not actions: no busy look */\n.aun-menu-item[disabled][aria-current='true'],\n.aun-menu-item[aria-disabled='true'].aun-menu-who-sub {\n  cursor: default;\n  opacity: 1;\n}\n.aun-menu-item > svg,\n.aun-menu-icon {\n  width: 1.125rem;\n  height: 1.125rem;\n  flex: none;\n  color: var(--aun-menu-muted);\n}\n.aun-menu-item > .aun-menu-text {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* the current page / app / choice */\n.aun-menu-item[aria-current]:not([aria-current='false']):not(.aun-menu-who),\n.aun-menu-item[aria-checked='true'],\n.aun-menu-item[aria-pressed='true'] {\n  background: var(--aun-menu-hover);\n  font-weight: 600;\n}\n.aun-menu-check {\n  width: 1rem;\n  height: 1rem;\n  flex: none;\n  margin-inline-start: auto;\n  color: var(--fanous-color-link);\n}\n/* sign out of every account */\n.aun-menu-item--danger,\n.aun-menu-item--danger > svg {\n  color: var(--fanous-color-error-text);\n}\n\n/* ---------- accounts in this browser ---------- */\n.aun-acct-row {\n  display: flex;\n  align-items: stretch;\n  gap: var(--fanous-spacing-xxs, 2px);\n}\n.aun-acct-row > .aun-menu-item {\n  flex: 1 1 auto;\n  min-width: 0;\n}\n.aun-acct-text {\n  display: flex;\n  flex: 1 1 auto;\n  flex-direction: column;\n  min-width: 0;\n}\n.aun-acct-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.aun-acct-row [aria-current='true'] .aun-acct-label {\n  font-weight: 600;\n}\n/* \"Sign out\" of one account: a small text button at the row's end */\n.aun-acct-signout {\n  flex: none;\n  align-self: center;\n  min-height: 2.75rem;\n  padding: 0 var(--fanous-spacing-sm, 8px);\n  border: 0;\n  border-radius: var(--fanous-radius-sm, 4px);\n  background: transparent;\n  color: var(--aun-menu-muted);\n  font: inherit;\n  font-size: 0.8125rem;\n  cursor: pointer;\n}\n.aun-acct-signout:hover {\n  background: var(--aun-menu-hover);\n  color: var(--aun-menu-text);\n}\n\n/* ---------- the context slot (NAV.md \"Slots\"): one app's own layer, e.g. the videos channel layer ---------- */\n.aun-menu-context {\n  display: flex;\n  flex-direction: column;\n}\n/* the current context (the active channel): avatar + name, like an account row */\n.aun-menu-context-current .aun-avatar {\n  width: 2rem;\n  height: 2rem;\n}\n/* a small role chip (\"Channel admin\") */\n.aun-badge {\n  flex: none;\n  margin-inline-start: auto;\n  padding: var(--fanous-spacing-xxs, 2px) var(--fanous-spacing-sm, 8px);\n  border: 1px solid var(--aun-menu-line);\n  border-radius: var(--fanous-radius-full, 999px);\n  color: var(--aun-menu-muted);\n  font-size: 0.6875rem;\n  font-weight: 600;\n  white-space: nowrap;\n}\n/* a line that explains why an action is missing (a limit reached) */\n.aun-menu-note {\n  margin: 0;\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-md, 12px);\n  color: var(--aun-menu-muted);\n  font-size: 0.8125rem;\n}\n/* an inline form (create a channel) */\n.aun-menu-form {\n  display: flex;\n  flex-direction: column;\n  gap: var(--fanous-spacing-sm, 8px);\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-md, 12px);\n}\n.aun-menu-form .aun-menu-label {\n  padding: 0;\n}\n.aun-menu-input {\n  box-sizing: border-box;\n  width: 100%;\n  min-height: 2.5rem;\n  padding: 0 var(--fanous-spacing-md, 12px);\n  border: 1px solid var(--aun-menu-line);\n  border-radius: var(--fanous-radius-sm, 4px);\n  background: transparent;\n  color: var(--aun-menu-text);\n  font: inherit;\n}\n.aun-menu-input:focus-visible {\n  outline: 2px solid var(--fanous-color-focus-ring);\n  outline-offset: -1px;\n}\n.aun-menu-form-actions {\n  display: flex;\n  gap: var(--fanous-spacing-sm, 8px);\n}\n.aun-menu-form-actions > * {\n  flex: 1 1 0;\n}\n\n/* directional icons (back, chevron, sign out) point the reading direction */\n[dir='rtl'] .aun-flip {\n  transform: scaleX(-1);\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  .aun-acct-btn,\n  .aun-icon-btn,\n  .aun-lang,\n  .aun-menu-item,\n  .aun-acct-signout {\n    transition: background-color var(--fanous-duration-fast, 120ms) ease;\n  }\n}\n";
